// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 0, 1e20);

        Receiver r = new Receiver();

        address funder = address(0xF00D);
        vm.deal(funder, amount);
        vm.prank(funder);
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent);

        uint256 before = address(c).balance;

        vm.assume(amount > 0);
        vm.assume(before >= amount);

        vm.prank(address(this));
        bool ok;
        try c.sendMoney(address(r), amount, "") {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 afterBal = address(c).balance;
        assertTrue(afterBal + amount == before && ok, "contract did not forward the full amount as expected");
    }
}

contract Receiver {
    receive() external payable {}
}
